<?php
require __DIR__.'/../database/runtime.php';$user=requireUser();rateLimit('scan:'.$user['id'],80,60);ensureSubscriptionSchema();$d=body();$token=trim((string)($d['token']??''));
$id='';$signed=false;
if(preg_match('/^EF1:([a-f0-9]{32})\.([a-f0-9]{64})$/',$token,$m)){$id=$m[1];$signed=hash_equals(hash_hmac('sha256','EF1.'.$id,ticketSecret()),$m[2]);}
elseif(preg_match('/^([a-f0-9]{32})\.([a-f0-9]{64})$/',$token,$m)){$id=$m[1];$signed=hash_equals(hash_hmac('sha256',$id,ticketSecret()),$m[2]);}
if(!$id||!$signed){$pdo->prepare('INSERT INTO audit_log(actor_email,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)')->execute([$user['email'],'ticket.scan_rejected_forged','ticket',substr(hash('sha256',$token),0,32),json_encode(['reason'=>'invalid_signature'])]);reply(['valid'=>false,'verdict'=>'forged','error'=>'QR falsifié ou signature invalide.'],422);}
$pdo->beginTransaction();try{
  $q=$pdo->prepare('SELECT t.id,t.booking_id,t.event_id,t.scanned_at,t.status,t.ticket_type_id,b.event_title,b.event_date,b.location,b.user_info,b.total,e.title AS actual_event,tt.name AS ticket_type FROM issued_tickets t JOIN bookings b ON b.id=t.booking_id JOIN events e ON e.id=t.event_id LEFT JOIN event_ticket_types tt ON tt.event_id=t.event_id AND tt.id=t.ticket_type_id WHERE t.id=? AND t.token_hash=? FOR UPDATE');$q->execute([$id,hash('sha256',$token)]);$t=$q->fetch();
  if(!$t){$pdo->rollBack();$pdo->prepare('INSERT INTO audit_log(actor_email,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)')->execute([$user['email'],'ticket.scan_rejected_unknown','ticket',$id,json_encode(['reason'=>'not_found'])]);reply(['valid'=>false,'verdict'=>'unknown','error'=>'Ticket inconnu.'],404);}
  requireEventAccess((int)$t['event_id']);
  $expected=(int)($d['eventId']??0);if($expected>0&&$expected!==(int)$t['event_id']){$pdo->rollBack();$pdo->prepare('INSERT INTO audit_log(actor_email,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)')->execute([$user['email'],'ticket.scan_rejected_other_event','ticket',$id,json_encode(['ticket_event_id'=>$t['event_id'],'gate_event_id'=>$expected])]);reply(['valid'=>false,'verdict'=>'other_event','error'=>'Ce billet concerne un autre événement ou une autre porte.'],409);}
  $status=$t['status']?:($t['scanned_at']?'used':'valid');
  if($status!=='valid'||$t['scanned_at']){$pdo->rollBack();$verdict=in_array($status,['cancelled','refunded','expired','transferred'],true)?$status:'used';$pdo->prepare('INSERT INTO audit_log(actor_email,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)')->execute([$user['email'],'ticket.scan_rejected_'.$verdict,'ticket',$id,json_encode(['status'=>$status,'event_id'=>$t['event_id']])]);reply(['valid'=>false,'verdict'=>$verdict,'error'=>$verdict==='used'?'Ce ticket a déjà été utilisé.':'Ce ticket est '.$verdict.'.','usedAt'=>$t['scanned_at']],409);}
  $pdo->prepare("UPDATE issued_tickets SET scanned_at=NOW(),status='used',entry_point=? WHERE id=? AND status='valid' AND scanned_at IS NULL")->execute([substr(trim((string)($d['entryPoint']??'')),0,100)?:null,$id]);
  $pdo->prepare('INSERT INTO audit_log(actor_email,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)')->execute([$user['email'],'ticket.checked_in','ticket',$id,json_encode(['event_id'=>$t['event_id'],'entry_point'=>$d['entryPoint']??null,'ticket_type'=>$t['ticket_type']])]);$pdo->commit();
  $person=json_decode($t['user_info'],true)?:[];reply(['valid'=>true,'verdict'=>'valid','eventId'=>(string)$t['event_id'],'eventTitle'=>$t['actual_event'],'date'=>$t['event_date'],'location'=>$t['location'],'zone'=>$t['ticket_type']?:'Standard','ticketType'=>$t['ticket_type']?:'Standard','user'=>$person,'total'=>(float)$t['total'],'bookingId'=>(string)$t['booking_id'],'purchaseDate'=>date(DATE_ATOM)]);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
